def check_graph(edges_list):
    if len(edges_list) % 2 != 0:
        return False, "Odd number of integers"
    edges = [(edges_list[i], edges_list[i+1]) for i in range(0, len(edges_list), 2)]
    if len(edges) < 19:
        return False, "Less than 19 edges"

    import networkx as nx
    G = nx.Graph()
    G.add_nodes_from(range(15))
    G.add_edges_from(edges)

    if G.number_of_edges() != len(edges):
        return False, "Duplicate edges"

    if not nx.is_bipartite(G):
        return False, "Not bipartite"

    cycles = nx.cycle_basis(G)
    if cycles:
        girth = min(len(c) for c in cycles)
        if girth < 4:
            return False, f"Girth is {girth}"

    return True, "Valid"

edges = [0, 7, 0, 8, 0, 9, 0, 10, 0, 11, 0, 12, 0, 13, 0, 14, 1, 7, 1, 8, 1, 9, 1, 10, 1, 11, 1, 12, 1, 13, 1, 14, 2, 7, 2, 8, 2, 9]
print(check_graph(edges))
